// Work out, for each Xero organisation, which changes to ask for (since its last successful check).
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
const last = sd.lastRunByTenant || {};
const fallback = new Date(Date.now() - Number(cfg.lookback_hours || 48) * 3600 * 1000);
const fmt = d => d.toISOString().slice(0, 19);
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const since = last[j.tenantId] ? new Date(last[j.tenantId]) : fallback;
  const withOverlap = new Date(since.getTime() - 5 * 60 * 1000); // 5 minute overlap so nothing falls between runs
  out.push({ json: { tenantId: j.tenantId, tenantName: j.tenantName, tenantType: j.tenantType, since_utc: fmt(withOverlap) }, pairedItem: { item: i } });
}
return out;

// Normalise the bills from every organisation, run the exception checks, and prepare one digest.
// Nothing is changed in Xero or in the workflow memory here; "Remember this run" saves state after the digest is sent.
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
const reportedSeen = sd.reported || {};
const billIndex = sd.billIndex || {};
const now = Date.now();
const DAY = 86400000;
const PAGE_SIZE = 100; // Xero returns at most 100 bills per page
const MAX_PAGES = Number(cfg.xero_max_pages || 10); // keep equal to "Max pages" in the pagination settings of both Xero bill nodes
const num = v => (v === null || v === undefined || v === '') ? null : Number(v);
const norm = v => String(v === null || v === undefined ? '' : v).toLowerCase().replace(/[^a-z0-9]/g, '');
// Bill number for matching: ignore punctuation, a leading letter prefix and leading zeros, so INV-0042, inv42 and 42 match.
const normNo = v => norm(v).replace(/^[a-z]+(?=\d)/, '').replace(/^0+(?=\d)/, '');
const toDate = s => {
  if (!s) return null;
  const m = /\/Date\((-?\d+)/.exec(String(s));
  if (m) return new Date(Number(m[1]));
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
};
const dayOf = (str, obj) => str ? String(str).slice(0, 10) : (toDate(obj) ? toDate(obj).toISOString().slice(0, 10) : '');
const dayMs = s => { const t = s ? new Date(String(s).slice(0, 10) + 'T00:00:00Z').getTime() : NaN; return isNaN(t) ? null : t; };
const r2 = n => Math.round(n * 100) / 100;

const orgs = $('Only organisations').all().map(i => i.json);
const orgNames = orgs.map(o => o.tenantName);
const expected = Number(cfg.expected_org_count || 0);
const orgWarning = expected > 0 && orgs.length !== expected
  ? 'Xero returned ' + orgs.length + ' connected organisations; expected ' + expected + '.' : '';

// ---- read every page from both queries ----
const errors = [];
const fetchState = {}; // tenant|query -> { tenant, name, query, bills, failed }
const bills = {};
for (const it of $input.all()) {
  const j = it.json || {};
  const tenant = j.tenant_id || '';
  const tname = j.tenant_name || '';
  const src = j.source_query || '';
  const fk = tenant + '|' + src;
  const st = fetchState[fk] = fetchState[fk] || { tenant: tenant, name: tname, query: src, bills: 0, failed: false };
  const invs = Array.isArray(j.Invoices) ? j.Invoices : null;
  if (j.error || invs === null) {
    st.failed = true;
    errors.push({ tenant: tname, query: src, message: String((j.error && (j.error.message || j.error.description)) || JSON.stringify(j.error || 'No invoice list returned')).slice(0, 300) });
    continue;
  }
  st.bills += invs.length;
  for (const inv of invs) {
    const key = tenant + '|' + inv.InvoiceID;
    if (!bills[key]) {
      const inclusive = String(inv.LineAmountTypes || '').toLowerCase() === 'inclusive';
      bills[key] = {
        tenant_id: tenant, company: tname, id: inv.InvoiceID, number: inv.InvoiceNumber || '',
        supplier: (inv.Contact && inv.Contact.Name) || '', status: inv.Status || '',
        date: dayOf(inv.DateString, inv.Date), due: dayOf(inv.DueDateString, inv.DueDate),
        total: num(inv.Total), subtotal: num(inv.SubTotal), tax: num(inv.TotalTax),
        currency: inv.CurrencyCode || '', reference: inv.Reference || '',
        has_attachments: inv.HasAttachments === true,
        updated: toDate(inv.UpdatedDateUTC) ? toDate(inv.UpdatedDateUTC).toISOString() : '',
        lines: (inv.LineItems || []).map(l => {
          const amount = num(l.LineAmount);
          const taxAmt = num(l.TaxAmount);
          return {
            description: l.Description || '', amount: amount, account: l.AccountCode || '',
            tax_type: l.TaxType || '', tax_amount: taxAmt,
            net: amount === null ? null : (inclusive && taxAmt !== null ? amount - taxAmt : amount),
            tracking: (l.Tracking || []).map(t => ({ name: t.Name || '', option: t.Option || '' }))
          };
        }),
        sources: []
      };
    }
    if (!bills[key].sources.includes(src)) bills[key].sources.push(src);
  }
}

// A query that filled every page it was allowed may have more bills waiting: report it and do not move that organisation's
// "checked up to" time forward, so the next run asks for the same window again instead of skipping the rest.
const changedOk = new Set();
for (const st of Object.values(fetchState)) {
  const truncated = !st.failed && st.bills >= MAX_PAGES * PAGE_SIZE;
  if (truncated) errors.push({ tenant: st.name, query: st.query, message: st.bills + ' bills returned, the most ' + MAX_PAGES + ' pages allow. Some bills were not checked this run; they will be asked for again next run. Raise "Max pages" on the Xero bill nodes and xero_max_pages in Config if this repeats.' });
  if (st.query === 'changed' && !st.failed && !truncated) changedOk.add(st.tenant);
}

const propName = norm(cfg.property_tracking_category);
const largeAmount = Number(cfg.large_amount || 0);
const staleDays = Number(cfg.stale_days || 3);
const dueSoonDays = Number(cfg.due_soon_days || 3);
const dupWindowDays = Number(cfg.dup_window_days || 6);
const oldBillDays = Number(cfg.old_bill_days || 180);
const vatRates = String(cfg.vat_rates || '0,5,20').split(',').map(s => Number(s.trim()) / 100).filter(r => !isNaN(r));
const routeAStatuses = String(cfg.route_a_statuses === undefined ? 'DRAFT,SUBMITTED' : cfg.route_a_statuses).split(',').map(s => s.trim().toUpperCase()).filter(Boolean);
const baseCurrency = String(cfg.base_currency || 'GBP').toUpperCase();
const orgNorm = new Set(orgNames.map(norm));
const runSeen = {};
const exceptions = [];
const reportedUpdates = {};
const indexUpdates = {};
const bucket = Math.floor(now / (3 * DAY));
const todayMs = dayMs(new Date(now).toISOString());

const propsOf = b => Array.from(new Set(b.lines.map(l => (l.tracking.find(t => norm(t.name) === propName && t.option) || {}).option).filter(Boolean).map(norm))).sort();

// Bills already known for the looser duplicate rule: earlier runs (memory) plus this run.
const amountEntries = Object.keys(billIndex).filter(k => k.indexOf('amt|') === 0).map(k => billIndex[k]);
const thisRun = Object.values(bills).filter(b => b.total !== null && b.total !== 0).map(b => ({ id: b.id, tenant_id: b.tenant_id, company: b.company, supplier_key: norm(b.supplier), total: r2(b.total), date: b.date, number: b.number, props: propsOf(b) }));

for (const b of Object.values(bills)) {
  const flags = [];
  const props = propsOf(b);
  // 1. Property on every line. Skipped for bills Route A already checks (route_a_statuses), since Route A emails those itself.
  if (b.lines.length && !routeAStatuses.includes(String(b.status || '').toUpperCase())) {
    const missing = b.lines.filter(l => !l.tracking.some(t => norm(t.name) === propName && t.option)).length;
    if (missing) flags.push({ code: 'missing_property', severity: 'high', message: missing + ' of ' + b.lines.length + ' lines have no "' + cfg.property_tracking_category + '" tracking option.' });
  }
  // 2. Source document attached
  if (!b.has_attachments) flags.push({ code: 'no_attachment', severity: 'warn', message: 'No invoice file is attached to this bill.' });
  // 3. Currency
  if (b.currency && b.currency.toUpperCase() !== baseCurrency) flags.push({ code: 'foreign_currency', severity: 'warn', message: 'Bill is in ' + b.currency + ': keep out of the GBP payment batch.' });
  // 4. Large amount
  if (largeAmount > 0 && b.total !== null && b.total >= largeAmount) flags.push({ code: 'large_amount', severity: 'warn', message: 'Total ' + b.total.toFixed(2) + ' is at or above ' + largeAmount + '.' });
  // 5. Supplier is another group company
  if (b.supplier && orgNorm.has(norm(b.supplier)) && norm(b.supplier) !== norm(b.company)) flags.push({ code: 'intercompany_counterparty', severity: 'info', message: 'Supplier is another group company: check the intercompany entry.' });

  // 6a. Duplicate: same supplier, bill number (INV-0042 = 42) and total, in any organisation
  let exactDup = false;
  if (b.number && b.total !== null) {
    const dk = norm(b.supplier) + '|' + normNo(b.number) + '|' + b.total.toFixed(2);
    const seen = billIndex[dk] || runSeen[dk];
    if (seen && (seen.id !== b.id || seen.tenant_id !== b.tenant_id)) {
      exactDup = true;
      flags.push({ code: 'possible_duplicate', severity: 'high', message: 'Same supplier, bill number and total already seen in ' + (seen.company || 'another bill') + (seen.number && seen.number !== b.number ? ' (as ' + seen.number + ')' : '') + '.' });
    }
    if (!seen) { indexUpdates[dk] = { ts: now, id: b.id, tenant_id: b.tenant_id, company: b.company, number: b.number }; runSeen[dk] = indexUpdates[dk]; }
  }
  // 6b. Looser duplicate: same supplier and total within dup_window_days, different bill number.
  //     Skipped when both bills name different properties (e.g. the same cleaning price for two flats).
  if (!exactDup && b.total !== null && b.total !== 0 && b.date) {
    const sk = norm(b.supplier), tot = r2(b.total), bMs = dayMs(b.date);
    const match = amountEntries.concat(thisRun).find(o =>
      !(o.id === b.id && o.tenant_id === b.tenant_id) && o.supplier_key === sk && o.total === tot && o.date &&
      Math.abs(dayMs(o.date) - bMs) <= dupWindowDays * DAY &&
      !(props.length && (o.props || []).length && props.join('|') !== (o.props || []).join('|')));
    if (match) flags.push({ code: 'possible_duplicate_similar', severity: 'warn', message: 'Same supplier and total as bill ' + (match.number || '(no number)') + ' dated ' + match.date + (match.company ? ' in ' + match.company : '') + '. Check it is not entered twice.' });
    const ak = 'amt|' + b.tenant_id + '|' + b.id;
    indexUpdates[ak] = { ts: now, id: b.id, tenant_id: b.tenant_id, company: b.company, supplier_key: sk, total: tot, date: b.date, number: b.number, props: props };
  }

  // 7. VAT
  if (b.subtotal !== null && b.tax !== null && b.total !== null && Math.abs(b.subtotal + b.tax - b.total) > 0.02) {
    flags.push({ code: 'vat_totals_mismatch', severity: 'warn', message: 'Subtotal ' + b.subtotal.toFixed(2) + ' + VAT ' + b.tax.toFixed(2) + ' does not equal the total ' + b.total.toFixed(2) + '.' });
  }
  const oddVat = b.lines.filter(l => {
    if (l.tax_amount === null || l.tax_amount === 0 || l.net === null) return false;
    if (l.net === 0) return true;
    const tol = Math.max(0.02, Math.abs(l.net) * 0.0025);
    return !vatRates.some(r => Math.abs(l.tax_amount - l.net * r) <= tol);
  });
  if (oddVat.length) {
    const eg = oddVat[0];
    const pct = eg.net ? (eg.tax_amount / eg.net * 100).toFixed(1) + '%' : 'VAT on a zero line';
    flags.push({ code: 'vat_rate_unusual', severity: 'warn', message: oddVat.length + ' line(s) have VAT that is not ' + vatRates.map(r => Math.round(r * 100) + '%').join(', ') + ' of the net amount (e.g. ' + eg.tax_amount.toFixed(2) + ' on ' + (eg.net || 0).toFixed(2) + ' = ' + pct + '). Check the VAT was not typed over.' });
  }

  // 8. Dates
  const dMs = dayMs(b.date), dueMs = dayMs(b.due);
  if (!b.date) flags.push({ code: 'missing_bill_date', severity: 'warn', message: 'Bill has no date.' });
  if (!b.due) flags.push({ code: 'missing_due_date', severity: 'warn', message: 'Bill has no due date, so it will not show in due-date payment runs.' });
  if (dMs !== null && dueMs !== null && dueMs < dMs) flags.push({ code: 'due_before_bill_date', severity: 'warn', message: 'Due date ' + b.due + ' is before the bill date ' + b.date + '.' });
  if (dMs !== null && dMs > todayMs + DAY) flags.push({ code: 'future_dated', severity: 'warn', message: 'Bill is dated ' + b.date + ', in the future.' });
  if (dMs !== null && oldBillDays > 0 && todayMs - dMs > oldBillDays * DAY) flags.push({ code: 'old_bill', severity: 'info', message: 'Bill is dated ' + b.date + ', more than ' + oldBillDays + ' days ago: check the date and that it has not been paid already.' });

  // 9. Not approved yet (matters for the Monday payment batch)
  if (b.status === 'DRAFT' || b.status === 'SUBMITTED') {
    const upd = toDate(b.updated);
    if (upd && (now - upd.getTime()) > staleDays * DAY) flags.push({ code: 'stale_unapproved', severity: 'warn', message: 'Waiting for approval for more than ' + staleDays + ' days (' + b.status + ').' });
    if (dueMs !== null && dueMs - now <= dueSoonDays * DAY) flags.push({ code: 'due_soon_unapproved', severity: 'high', message: 'Due ' + b.due + ' and not yet approved.' });
  }
  // Report each issue once per bill version (stale and due-soon repeat every 3 days)
  const fresh = [];
  for (const f of flags) {
    const repeat = (f.code === 'stale_unapproved' || f.code === 'due_soon_unapproved') ? ('|' + bucket) : '';
    const rk = b.tenant_id + '|' + b.id + '|' + b.updated + '|' + f.code + repeat;
    if (!reportedSeen[rk]) { fresh.push(f); reportedUpdates[rk] = now; }
  }
  if (fresh.length) exceptions.push({ company: b.company, supplier: b.supplier, number: b.number, date: b.date, due: b.due, status: b.status, total: b.total, currency: b.currency, id: b.id, flags: fresh, link: 'https://go.xero.com/AccountsPayable/View.aspx?invoiceID=' + b.id });
}
exceptions.sort((a, b) => (a.company || '').localeCompare(b.company || '') || (a.supplier || '').localeCompare(b.supplier || ''));

return [{ json: {
  generated_at: new Date(now).toISOString(),
  org_count: orgs.length, org_names: orgNames, org_warning: orgWarning,
  bills_checked: Object.keys(bills).length,
  exceptions: exceptions, errors: errors,
  changed_ok_tenants: Array.from(changedOk),
  reported_updates: reportedUpdates, index_updates: indexUpdates,
  bills: Object.values(bills).map(b => ({ company: b.company, tenant_id: b.tenant_id, id: b.id, number: b.number, supplier: b.supplier, date: b.date, total: b.total, currency: b.currency, status: b.status, lines: b.lines }))
} }];

// Build one digest email, grouped by company.
const cfg = $('Config').first().json;
const f = $input.first().json;
const esc = v => String(v === null || v === undefined ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const th = 'style="text-align:left;background:#f2f4f7;padding:6px 10px;border:1px solid #d0d5dd;white-space:nowrap;vertical-align:top"';
const td = 'style="padding:6px 10px;border:1px solid #d0d5dd;vertical-align:top"';
const tbl = 'style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:13px;margin-bottom:16px"';
const colour = { high: '#b42318', warn: '#b54708', info: '#475467' };
const money = (n, c) => n === null || n === undefined ? '-' : (c ? c + ' ' : '') + Number(n).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
let html = '<h2 style="font-family:Arial,sans-serif;margin:0 0 4px">Xero bill exceptions</h2>' +
  '<p style="font-family:Arial,sans-serif;font-size:13px;color:#475467;margin:0 0 12px">' + esc(f.bills_checked) + ' bills checked across ' + esc(f.org_count) + ' Xero organisations. Read-only: nothing was changed in Xero.</p>';
if (f.org_warning) html += '<p style="font-family:Arial,sans-serif;font-size:13px;color:#b42318"><b>' + esc(f.org_warning) + '</b></p>';
if ((f.errors || []).length) {
  html += '<h3 style="font-family:Arial,sans-serif;margin:12px 0 6px">Checks that failed</h3><table ' + tbl + '><tr><th ' + th + '>Company</th><th ' + th + '>Query</th><th ' + th + '>Problem</th></tr>';
  for (const e of f.errors) html += '<tr><td ' + td + '>' + esc(e.tenant) + '</td><td ' + td + '>' + esc(e.query) + '</td><td ' + td + '>' + esc(e.message) + '</td></tr>';
  html += '</table>';
}
const byCo = {};
for (const e of (f.exceptions || [])) (byCo[e.company] = byCo[e.company] || []).push(e);
for (const co of Object.keys(byCo)) {
  html += '<h3 style="font-family:Arial,sans-serif;margin:12px 0 6px">' + esc(co) + ' (' + byCo[co].length + ')</h3>' +
    '<table ' + tbl + '><tr><th ' + th + '>Supplier</th><th ' + th + '>Bill</th><th ' + th + '>Date</th><th ' + th + '>Due</th><th ' + th + '>Status</th><th ' + th + '>Total</th><th ' + th + '>Issues</th><th ' + th + '>Open</th></tr>';
  for (const e of byCo[co]) {
    const issues = e.flags.map(x => '<span style="color:' + (colour[x.severity] || '#344054') + '"><b>' + esc(x.code) + '</b>: ' + esc(x.message) + '</span>').join('<br>');
    html += '<tr><td ' + td + '>' + esc(e.supplier) + '</td><td ' + td + '>' + esc(e.number || '-') + '</td><td ' + td + '>' + esc(e.date) + '</td><td ' + td + '>' + esc(e.due) + '</td><td ' + td + '>' + esc(e.status) + '</td><td ' + td + ' align="right">' + esc(money(e.total, e.currency)) + '</td><td ' + td + '>' + issues + '</td><td ' + td + '><a href="' + esc(e.link) + '">Xero</a></td></tr>';
  }
  html += '</table>';
}
const n = (f.exceptions || []).length;
const subject = '[Xero watcher] ' + n + ' bill exception' + (n === 1 ? '' : 's') + (Object.keys(byCo).length ? ' in ' + Object.keys(byCo).length + ' compan' + (Object.keys(byCo).length === 1 ? 'y' : 'ies') : '') + ((f.errors || []).length ? ', ' + f.errors.length + ' check(s) failed' : '');
return [{ json: { mail: { message: { subject: subject, body: { contentType: 'HTML', content: html }, toRecipients: String(cfg.digest_to || '').split(/[,;]/).map(s => s.trim()).filter(Boolean).map(a => ({ emailAddress: { address: cfg.noreply_address } })) }, saveToSentItems: false } } }];

// Save what this run saw, only after the digest was sent (or nothing needed sending).
const f = $('Flatten bills and check').first().json;
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
const now = Date.now();
sd.lastRunByTenant = sd.lastRunByTenant || {};
for (const t of (f.changed_ok_tenants || [])) sd.lastRunByTenant[t] = cfg.run_started_at;
sd.reported = Object.assign(sd.reported || {}, f.reported_updates || {});
sd.billIndex = Object.assign(sd.billIndex || {}, f.index_updates || {});
for (const k of Object.keys(sd.reported)) if (now - sd.reported[k] > 30 * 86400000) delete sd.reported[k];
for (const k of Object.keys(sd.billIndex)) if (now - sd.billIndex[k].ts > 120 * 86400000) delete sd.billIndex[k];
const keys = Object.keys(sd.billIndex);
if (keys.length > 3000) { keys.sort((a, b) => sd.billIndex[a].ts - sd.billIndex[b].ts).slice(0, keys.length - 3000).forEach(k => delete sd.billIndex[k]); }
return [{ json: { remembered: true, tenants_updated: (f.changed_ok_tenants || []).length, reported_keys: Object.keys(sd.reported).length, bill_index_size: Object.keys(sd.billIndex).length } }];
